parameters.jsCode:
const response = $input.first().json;
const textContent = response.candidates[0].content.parts[0].text;
const cleaned = textContent.replace(/```json|```/g, '').trim();
const hasil = JSON.parse(cleaned);

return [{ json: hasil }];
